import json, os, subprocess, threading, queuefrom datetime import datetimefrom .database import SessionLocalfrom .models import Scan_LOG_LOCK = threading.Lock()_LIVE_LOGS: dict[int, list[str]] = {}_JOB_QUEUE: "queue.Queue" = queue.Queue()_worker_started = False_worker_lock = threading.Lock()def _append_log(scan_id: int, line: str):    with _LOG_LOCK:        _LIVE_LOGS.setdefault(scan_id, []).append(line)def _flush_and_clear(scan_id: int) -> str:    with _LOG_LOCK:        lines = _LIVE_LOGS.pop(scan_id, [])    return "\n".join(lines)def get_live_log(scan_id: int) -> str | None:    with _LOG_LOCK:        if scan_id in _LIVE_LOGS:            return "\n".join(_LIVE_LOGS[scan_id])    return Nonedef _read_stderr(pipe, scan_id: int):    for line in iter(pipe.readline, ""):        if line:            _append_log(scan_id, line.rstrip())    pipe.close()def _execute_scan(scan_id: int, image: str, reg_user: str | None, reg_pass: str | None,                  scan_secrets: bool):    db = SessionLocal()    scan = db.get(Scan, scan_id)    scan.status = "running"    scan.secrets_enabled = scan_secrets    db.commit()    env = os.environ.copy()    if reg_user and reg_pass:        env["TRIVY_USERNAME"] = reg_user        env["TRIVY_PASSWORD"] = reg_pass    scanners = "vuln,secret" if scan_secrets else "vuln"    proc = None    timer = None    try:        proc = subprocess.Popen(            ["trivy", "image", "--format", "json",             "--timeout", "25m", "--scanners", scanners, image],            stdout=subprocess.PIPE, stderr=subprocess.PIPE,            text=True, env=env,        )        timer = threading.Timer(1800, proc.kill)        timer.start()        t = threading.Thread(target=_read_stderr, args=(proc.stderr, scan_id), daemon=True)        t.start()        stdout_data = proc.stdout.read()        proc.wait()        t.join(timeout=5)        if proc.returncode != 0:            raise RuntimeError(get_live_log(scan_id) or "Trivy zwrócił błąd")        report = json.loads(stdout_data)        counts = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0, "UNKNOWN": 0}        secrets_total = 0        for result in report.get("Results") or []:            for v in result.get("Vulnerabilities") or []:                sev = v.get("Severity", "UNKNOWN")                counts[sev] = counts.get(sev, 0) + 1            secrets_total += len(result.get("Secrets") or [])        scan.result_json = stdout_data        scan.critical, scan.high = counts["CRITICAL"], counts["HIGH"]        scan.medium, scan.low, scan.unknown = counts["MEDIUM"], counts["LOW"], counts["UNKNOWN"]        scan.secrets_found = secrets_total        scan.status = "done"    except Exception as e:        scan.status = "error"        scan.error = str(e)[-2000:]    finally:        if timer:            timer.cancel()        scan.log = _flush_and_clear(scan_id)        scan.finished_at = datetime.utcnow()        db.commit()        db.close()def _worker_loop():    while True:        job = _JOB_QUEUE.get()        try:            job()        except Exception:            pass        finally:            _JOB_QUEUE.task_done()def ensure_worker_started():    global _worker_started    with _worker_lock:        if not _worker_started:            t = threading.Thread(target=_worker_loop, daemon=True)            t.start()            _worker_started = Truedef submit_job(fn):    ensure_worker_started()    _JOB_QUEUE.put(fn)def enqueue_scan(scan_id: int, image: str, reg_user: str | None, reg_pass: str | None,                 scan_secrets: bool = False):    def job():        _execute_scan(scan_id, image, reg_user, reg_pass, scan_secrets)    submit_job(job)def queue_length() -> int:    return _JOB_QUEUE.qsize()